	"automation_lp_description": "ऑटोमेटेड खाते X API के माध्यम से कुछ कार्यों को स्वचालित रूप से करने के लिए प्रोग्राम किए जाते हैं. उदाहरण के लिए, किसी क्षेत्र की मौसम की स्थिति के बारे में पोस्ट करना. इन्हें X पर मौजूद अन्य लोगों द्वारा बनाया और प्रबंधित किया जाता है.",
	"automation_lp_description_2": "हाँ, सभी ऑटोमेटेड खातों को लेबल करना होता है. ऐसा करना हमारे {{}}नए नियमों{{}} के तहत ज़रूरी है.",
	"automation_lp_description_contd": "\"लेबल से सभी को पता चल जाता है कि ऑटोमेटेड खाते का प्रबंधन कौन कर रहा है.\n\nजब किसी ऑटोमेटेड खाते का स्वामी अपने प्रबंधन खाते को कनेक्ट कर देता है, तो ऑटोमेटेड खाता प्रोफ़ाइल और पोस्ट्स पर एक लेबल दिखाई देने लगता है.\"",
	"automation_lp_footer_description": "{{}}ऑटोमेटेड खाता लेबल के बारे में सामान्य प्रश्न{{}} पेज पर अधिक जानें.",
