	"face_liveness_introduction_disclaimer": "ऐप संक्षिप्त रूप में एक फ़ोटो लेगा और उसे AWS को भेजेगा, केवल यह पुष्टि करने के लिए कि आप एक वास्तविक व्यक्ति हैं और न कि कोई बॉट हैं। इसे X पर कभी नहीं भेजा जाता है और इसे AWS द्वारा सत्यापन के तुरंत बाद हटा दिया जाता है। इसका उपयोग एंटी-बॉट उपायों के अलावा किसी अन्य उद्देश्य के लिए नहीं किया जाता है। इसे बेचा नहीं जाएगा, पट्टे पर नहीं दिया जाएगा, या इसका ट्रेड नहीं किया जाएगा।",
	"face_liveness_introduction_disclaimer_v2": "हम आपकी तस्वीर AWS को केवल यह सत्यापित करने के लिए भेजेंगे कि आप बॉट नहीं हैं। आपकी फ़ोटो को कभी भी X पर नहीं भेजा जाता है, 3 मिनट के भीतर हटा दिया जाता है, और किसी अन्य उद्देश्य के लिए बेचा या उपयोग नहीं किया जाता है। जारी रखकर, आप बायोमेट्रिक डेटा प्रोसेसिंग के लिए सहमति देते हैं।",
