	"gift_premium_terms_footer": "उपहार सब्सक्रिप्शन के पैसे खरीदारी करते समय लिया जाता है और यह वापसी योग्य नहीं है। यह एक बार उपयोग करने योग्य, बदली न किए जाने वाला, गैर-संयोजन योग्य है और इसका कोई नकद मूल्य नहीं है। यह X की समीक्षा और प्राप्तकर्ता को सौंपने के बाद शुरू होता है, जिसे हमारी %1$s और नीतियों को स्वीकार करना होगा। यदि प्राप्तकर्ता किसी भी पात्रता आवश्यकताओं को पूरा करने में विफल रहता है, सब्सक्रिप्शन रद्द कर देता है या हमारी शर्तों और नीतियों को अस्वीकार कर देता है, तो उपहार गैर-प्रतिदेय और गैर-वापसी योग्य है. कर लागू हो सकते हैं। शर्तें बदल सकती हैं। %2$s।",
