	"golive__tip_broadcaster_1": "<b>टिप:</b> लाइव होने के लिए धन्यवाद! जब लोग आपके वीडियो में शामिल हों तो \\\"नमस्कार\\\" कहकर उनका स्वागत करें.",
	"golive__tip_broadcaster_10": "<b>युक्ति:</b> X पर लाइव होने के लिए धन्यवाद! ≺3",
	"golive__tip_broadcaster_2": "<b>टिप:</b> अपने लाइव वीडियो में शामिल होने वाले दर्शकों को उनके नाम से बुलाएं — वे रोमांचित हो जायेंगे!",
	"golive__tip_broadcaster_3": "<b>टिप:</b> लोग आपको आसानी से ढूंढ सकें इसके लिए कम से कम कुछ मिनट के लिए लाइव जरूर हों.",
	"golive__tip_broadcaster_4": "<b>टिप:</b> अपने दर्शकों से पूछें कि वे कहाँ से हैं — यह बातचीत शुरू करने का एक शानदार तरीका है.",
	"golive__tip_broadcaster_5": "<b>टिप:</b> शामिल होने के लिए लोगों को धन्यवाद दें और वे देखते रहें इसके लिए उनकी टिप्पणियों का जवाब दें.",
	"golive__tip_broadcaster_6": "<b>टिप:</b> यदि लाइव होते समय कनेक्शन टूट जाए, तो किसी ऐसा जगह जाएं जहाँ बेहतर सिगनल हो.",
	"golive__tip_broadcaster_7": "<b>टिप:</b> लोगों को आपको फ़ॉलो करने के लिए कहें ताकि अगली बार आपके लाइव होने पर उनको सूचना मिल सके.",
	"golive__tip_broadcaster_8": "<b>टिप:</b> अभी \\\"नमस्कार\\\" कहकर अपना लाइव वीडियो शुरू करें. बाद में देख रहे लोगों को यह पसंद आएगा.",
	"golive__tip_broadcaster_9": "<b>टिप:</b> अपने लाइव वीडियो को समाप्त करने से पहले लोगों को देखने के लिए धन्यवाद दें.",
	"golive__tip_pre_broadcast_1": "<b>टिप:</b> लाइव होने से पहले एक शीर्षक लिख कर लोगों की आपके वीडियो को खोजने में मदद करें.",
	"golive__tip_pre_broadcast_2": "<b>टिप:</b> एक वर्णनात्मक शीर्षक लोगों की यह समझने में मदद करता है कि आपका लाइव वीडियो किस बारे में है.",
	"golive__tip_pre_broadcast_3": "<b>टिप:</b> कुछ आइडिया चाहिए? एक टूर दें, टैलेंट शेयर करें, या अपनी रुचि की चीजों के बारे में बातचीत करें.",
	"golive__tip_pre_broadcast_4": "<b>टिप:</b> लाइव होने से पहले सुनिश्चित करें कि आपके पास एक मजबूत फ़ोन सिगनल है.",
	"golive__tip_pre_broadcast_5": "<b>टिप:</b> अपने शीर्षक में एक हैशटैग जोड़कर लोगों की आपके लाइव प्रसारण को खोजने में मदद करें.",
	"golive__tip_pre_broadcast_6": "<b>टिप:</b> हमारे पास अभी तक जितनी भी टिप्स थीं, हमने सब आपको बता दीं — X पर लाइव होने के लिए धन्यवाद!",
