	"identity_description": "Premium सब्सक्राइबर के रूप में अपनी पहचान की पुष्टि करने और फ़ीचर्स को अनलॉक करने के लिए सरकार द्वारा जारी अपनी ID सत्यापित करें.",
	"identity_education_camera_permissions": "आपकी पहचान सत्यापित करने के लिए, हमें आपके कैमरे के एक्सेस की आवश्यकता होगी",
