	"identity_education_conditions": "मैं अपनी पहचान की पुष्टि करने और प्रतिरूपण को रोकने सहित X के संबंधित सलामती एवं सुरक्षा उद्देश्यों के लिए X और Au10tix को अपनी ID और अपनी सेल्फ़ी की इमेजेज़ का उपयोग करने की सहमति देता/देती हूं, जिसमें निकाला गया बायोमेट्रिक डेटा भी शामिल है. Au10tix ऐसे डेटा को 30 दिनों तक के लिए स्टोर कर सकता है. {{}}अधिक जानें{{}}",
	"identity_education_conditions_age_verification": "मैं X और Persona को मेरी उम्र की पुष्टि के लिए मेरी ID और मेरी फ़ोटो इस्तेमाल करने की सहमति दे रहा/रही हूं. आपकी फ़ोटो संग्रहीत नहीं की जाएगी. X और xAI आपकी उम्र की जानकारी रख सकते हैं. {{}}अधिक जानें{{}}",
	"identity_education_conditions_eea": "\"मैं अपनी पहचान की पुष्टि करने के उद्देश्य से X को अपनी प्रोफ़ाइल से बायोमेट्रिक डेटा और व्यक्तिगत डेटा सहित अपनी ID की इमेजेज़ को Au10tix के साथ शेयर करने की सहमति देता/देती हूं.\nमैं X पर बायोमेट्रिक डेटा सहित मेरी ID इमेजेज़ को 30 दिनों तक संग्रहित करने और प्रतिरूपण को रोकने सहित सुरक्षा के प्रयोजनों के लिए इसका इस्तेमाल करने और मेरी प्रोफ़ाइल से डेटा का इस्तेमाल करने की भी सहमति देता/देती हूं. {{}}अधिक जानें{{}}\"",
	"identity_education_conditions_persona_vendor": "मैं X और Persona को मेरी पहचान की पुष्टि करने और X की संबंधित सुरक्षा और सुरक्षा, धोखाधड़ी की रोकथाम और भुगतान उद्देश्यों के लिए निकाले गए बायोमेट्रिक डेटा सहित मेरी ID और मेरी सेल्फी की छवियों का उपयोग करने के लिए सहमत हूं. Persona इस तरह के डेटा को 30 दिनों तक संग्रहीत कर सकता है. जब तक मैं X Premium सेवा को सब्सक्राइब करता हूं, तब तक X मेरा पूरा नाम, पता और मेरे दस्तावेज़ ID नंबर के हैश को संग्रहीत कर सकता है. {{}}अधिक जानें{{}}",
