	"palm_liveness_introduction_disclaimer": "ऐप आपके हाथ की गति को केवल यह पुष्टि करने के लिए संक्षिप्त रूप से कैप्चर करेगा कि आप एक वास्तविक व्यक्ति हैं और न कि कोई बॉट हैं। आपके हाथ की गति को कभी भी वीडियो के रूप में रिकॉर्ड नहीं किया जाता है और यह आपके डिवाइस को कभी नहीं छोड़ता है। इसका उपयोग एंटी-बॉट सत्यापन के अलावा किसी अन्य उद्देश्य के लिए नहीं किया जाता है, और इसे बेचा नहीं जाएगा, पट्टे पर नहीं दिया जाएगा, या इसका ट्रेड नहीं किया जाएगा।",
