	"payment_funds_insurance_footer_secondary_text": "FDIC बीमा और खाता स्वामित्व श्रेणियों के बारे में अधिक जानकारी ﻿यहाँ﻿देखें।",
	"payment_funds_insurance_footer_text": "आपकी जमा राशि क्रॉस रिवर बैंक, सदस्य FDIC के पास होती है और बैंक (संयुक्त) में आयोजित प्रत्येक खाता स्वामित्व श्रेणी के सभी खातों के लिए प्रति व्यक्ति $250,000 तक FDIC द्वारा बीमा किया जाता है और प्रतिनिधि क्षमता में रखे गए खातों सहित बैंक (संयुक्त) में आयोजित प्रत्येक खाता स्वामित्व श्रेणी के सभी खातों के लिए प्रति व्यक्ति और प्रति कानूनी इकाई के लिए FDIC द्वारा बीमा किया जाता है।",
	"payment_funds_insurance_footer_text_format": "आपकी जमा राशि Cross River Bank (बैंक), सदस्य FDIC द्वारा रखी जाती है और बैंक में रखे गए प्रत्येक खाता स्वामित्व श्रेणी के सभी खातों (संयुक्त रूप से), जिनमें प्रतिनिधि क्षमता में रखे गए खाते भी शामिल हैं, के लिए प्रति व्यक्ति और प्रति कानूनी इकाई के लिए FDIC द्वारा {amount} तक बीमाकृत है.",
	"payment_funds_insurance_sweep_disclaimer": "जमा Cross River Bank, जो FDIC का सदस्य है और अन्य ﻿FDIC- बीमाकृत संस्थानों﻿ में रखे जाते हैं। पास-थ्रू डिपॉज़िट इंश्योरेंस कवरेज के लिए आवेदन करने के लिए ﻿कुछ शर्तों﻿ को पूरा करना होगा। X Payments LLC एक FDIC- बीमाकृत बैंक नहीं है। डिपॉजिट इंश्योरेंस केवल बीमाकृत बैंक की विफलता को कवर करता है।",
	"payment_funds_insurance_sweep_presentation": "आपकी जमा राशि स्वचालित रूप से X Cash Sweep Program में नामांकित हो जाती है, जो कुछ सीमाओं के अधीन कुल मिलाकर $10M तक का FDIC बीमा कवरेज प्रदान करता है। ﻿अधिक जानें﻿।",
