	"profile_smart_blocked_autoblocked_by_twitter_description": "\"आपको @%1$sके पोस्ट्स देखने और उनसे इंटरैक्ट करने से अस्थायी रूप से ऑटो ब्लॉक किया गया है. यह तब हुआ जब वे सेफ्टी मोड में थे और हमने आपकी बातचीत को संभावित रूप से अपमानजनक भाषा या स्पैम के रूप में चिह्नित किया.\n\nहम जानते हैं कि हमारे द्वारा ऑटो ब्लॉक करना हमेशा सही नहीं होता है, इसलिए हम इसकी पहचान करने को बेहतर बनाने के लिए काम कर रहे हैं.\n\n{{}}सेफ्टी%2$sमोड%2$sक्या{{}}है?\n\nयहां कुछ तरीके दिए गए हैं जिनसे आप अपनी बातचीत को सकारात्मक रख सकते हैं — और ऑटो ब्लॉक होने से बच सकते हैं.\"",
