	"ps__report_broadcast_dialog_hateful_conduct_message": "अगर आपको लगता है कि यह प्रसारण किसी संरक्षित वर्ग (उदा, जाति, धर्म, लिंग, अभिविन्यास, विकलांगता) के खिलाफ नफरत भड़काता है, तो कृपया नीचे टैप करें.",
	"ps__report_broadcast_dialog_private_information_message": "अगर आपको लगता है कि यह प्रसारण निजी जानकारी को उजागर करता है, तो कृपया नीचे टैप करें.",
	"ps__report_broadcast_dialog_self_harm_message": "अगर आपको लगता है कि इस व्यक्ति का आत्महत्या करने या खुद को नुकसान पहुंचाने या दूसरों को इसके लिए उकसाने का इरादा है, तो कृपया नीचे टैप करें.",
	"ps__report_broadcast_dialog_sexual_content_message": "अगर आपको लगता है कि यह प्रसारण अश्लील सामग्री या यौन कृत्यों को दर्शाता है, तो कृपया नीचे टैप करें.",
	"ps__report_broadcast_dialog_violence_message": "अगर आपको लगता है कि इस प्रसारण में शारीरिक सुरक्षा या कल्याण से जुड़ी विशिष्ट हिंसक धमकियाँ हैं, तो कृपया नीचे टैप करें.",
	"ps__report_broadcast_error": "क्षमा करें, इस प्रसारण की रिपोर्ट करते हुए हमें एक त्रुटि मिली. कृपया पुनः प्रयास करें.",
