	"ps__report_broadcast_replay_prompt": "%1$s पर दिखाई देने वाली समस्या के बारे में बताएं",
	"ps__report_broadcast_success": "धन्यवाद, हमने आपकी रिपोर्ट सबमिट कर दी है",
	"ps__report_guest_dialog_abusive_behavior_message": "अगर आपको लगता है कि यह अतिथि उत्पीड़न कर रहा है, धमकी दे रहा है या किसी दूसरे व्यक्ति की आवाज़ को दबाने के लिए डर का उपयोग कर रहा है, तो कृपया नीचे टैप करें.",
	"ps__report_guest_dialog_child_safety_message": "अगर आपको लगता है कि यह अतिथि ऐसी सामग्री शेयर कर रहा है जो किसी बच्चे को खतरे में डालती है, तो कृपया नीचे टैप करें.",
	"ps__report_guest_dialog_dont_like_message": "\"आप उस उपयोगकर्ता को अवरुद्ध कर सकते हैं जिसके प्रसारण अब आप नहीं देखना चाहते. जिन उपयोगकर्ताओं को अपने अवरुद्ध किया है अगर वे अतिथि के रुप में आएंगे, तो आप उन्हें देख पाएंगे.\n\nअवरुद्ध करने से Periscope को @%1$s की रिपोर्ट नहीं की जाएगी.\"",
	"ps__report_guest_dialog_hateful_conduct_message": "अगर आपको लगता है कि यह अतिथि किसी संरक्षित वर्ग (उदा, जाति, धर्म, लिंग, अभिविन्यास, विकलांगता) के खिलाफ नफरत भड़का रहा है, तो कृपया नीचे टैप करें.",
	"ps__report_guest_dialog_private_information_message": "अगर आपको लगता है कि यह अतिथि निजी जानकारी को उजागर कर रहा है, तो कृपया नीचे टैप करें.",
	"ps__report_guest_dialog_self_harm_message": "अगर आपको लगता है कि इस अतिथि का आत्महत्या करने या खुद को नुकसान पहुंचाने या दूसरों को इसके लिए उकसाने का इरादा है, तो कृपया नीचे टैप करें.",
	"ps__report_guest_dialog_sexual_content_message": "अगर आपको लगता है कि यह अतिथि अश्लील सामग्री जैसे अनुचित यौन सामग्री शेयर कर रहा है, तो कृपया नीचे टैप करें.",
