	"ps__time_unit_seconds": "से",
	"ps__tip_broadcaster_1": "<b>टिप:</b> प्रसारण करने के लिए धन्यवाद! लोगों के शामिल होने पर उन्हें नमस्कार कहना याद रखें.",
	"ps__tip_broadcaster_11": "<b>टिप:</b> Periscope पर प्रसारण के लिए धन्यवाद! ≺3",
	"ps__tip_broadcaster_2": "<b>टिप:</b> शामिल होने वाले दर्शकों को उनके नाम से बुलाएं; वे रोमांचित हो जायेंगे!",
	"ps__tip_broadcaster_3": "<b>सुझाव:</b> लोग आपको आसानी से ढूंढ सकें इसके लिए कम से कम कुछ मिनट प्रसारण जरूर करें.",
	"ps__tip_broadcaster_4": "<b>टिप:</b> अपने दर्शकों से यह पूछना कि वे कहाँ से हैं, बातचीत शुरू करने का एक शानदार तरीका है.",
	"ps__tip_broadcaster_5": "<b>सुझाव:</b> शामिल होने के लिए दर्शकों को धन्यवाद दें और उन्हें जोड़े रखने के लिए उनकी टिप्पणियों का जवाब दें.",
	"ps__tip_broadcaster_6": "<b>सुझाव:</b> यदि प्रसारण करते समय कनेक्शन टूट जाए, तो किसी ऐसा जगह जाएं जहाँ बेहतर सिगनल हो.",
	"ps__tip_broadcaster_7": "<b>टिप:</b> अपने दर्शकों को आपको फ़ॉलो करने के लिए कहें ताकि आपके लाइव होने पर उनको सूचना मिल सके.",
	"ps__tip_broadcaster_8": "<b>सुझाव:</b> अभी नमस्कार कहकर अपना प्रसारण शुरू करें. आपके रीप्ले दर्शकों को यह पसंद आएगा.",
	"ps__tip_broadcaster_9": "<b>टिप:</b> अपने प्रसारण को समाप्त करने से पहले अपने दर्शकों को उसे देखने के लिए धन्यवाद कहें.",
	"ps__tip_pre_broadcast_1": "<b>टिप:</b> अपना प्रसारण शुरू करने से पहले एक शीर्षक लिखें और समान रुचियों वाले लोगों से मिलें!",
	"ps__tip_pre_broadcast_2": "<b>टिप:</b> एक वर्णनात्मक शीर्षक लोगों की यह समझने में मदद करता है कि आपका प्रसारण किस बारे में है.",
	"ps__tip_pre_broadcast_3": "<b>टिप:</b> कुछ आइडिया चाहिए? एक टूर दें, टैलेंट शेयर करें, या अपनी रुचि के विषय के बारे में बातचीत करें.",
	"ps__tip_pre_broadcast_4": "<b>टिप:</b> लाइव होने से पहले सुनिश्चित करें कि आपके पास एक मजबूत फ़ोन सिगनल है.",
	"ps__tip_pre_broadcast_5": "<b>युक्ति:</b> ज्यादा से ज्यादा दर्शकों तक पहुँचने के लिए अपने प्रसारणों को X पर शेयर करें.",
	"ps__tip_pre_broadcast_6": "<b>सुझाव:</b> अगर आप ऐसे लोगों को फ़ॉलो करते हैं जो वापस आपको फ़ॉलो करते हैं, तो आप उनके लिए निजी तौर पर प्रसारण कर सकते हैं.",
	"ps__tip_pre_broadcast_8": "<b>सुझाव:</b> अपने शीर्षक में एक प्रासंगिक हैशटैग जोड़कर लोगों की आपके प्रसारण को खोजने में मदद करें.",
	"ps__tip_pre_broadcast_9": "<b>सुझाव:</b> हमारे पास अभी तक जितनी भी टिप्स थीं, हमने सब आपको बता दीं, Periscope का उपयोग करने के लिए धन्यवाद!",
	"ps__tip_viewer_1": "<b>टिप:</b> आप शामिल होने वाले पहले कुछ लोगों में से एक है, टिप्पणी लिखें और नमस्कार कहें!",
	"ps__tip_viewer_2": "<b>टिप:</b> एक टिप्पणी लिखें और <b>%1$s</b> को जानने दें कि आप यहाँ हैं!",
	"ps__tip_viewer_3": "<b>टिप:</b> <b>%1$s</b> को जानने दें कि आप कहाँ से देख रहे हैं!",
	"ps__tip_viewer_4": "<b>टिप:</b> <b>%1$s</b> और अन्य दर्शकों के साथ चैट करने के लिए नमस्कार कहें.",
	"ps__toast_broadcast_notify_followers": "हमने आपके फ़ॉलोअर्स को बता दिया है कि आप एक अतिथि के रूप में शामिल हुए हैं",
