	"room_settings_clips": "क्लिप्स",
	"room_settings_clips_description": "\"जब आप कोई क्लिप बनाते हैं, तो वह पिछले 30 सेकंड के ऑडियो को कैप्चर करेगा. \n \nहोस्ट के रूप में, आप अपने स्पेस के उन क्लिप्स को मिटा सकते हैं जिन्हें अन्य लोगों ने बनाया है. लेकिन अगर आप अपने स्पेस से एक क्लिप मिटाते हैं, तो उसी स्पेस के सभी क्लिप मिट जाएंगे. \n \nअगर आप कोई स्पेस रिकॉर्ड करते हैं और उसके बाद उसे मिटा देते हैं, तो उस स्पेस के सभी क्लिप भी मिट जाएंगे. \n \nसभी क्लिप 30 दिनों के बाद समाप्त हो जाते हैं.\"",
