	"settings_audiospace_share_listening_data_summary": "\"अपने फ़ॉलोअर्स को यह देखने की अनुमति दें कि आप किन Spaces को सुन रहे हैं.\n\nध्यान रखें कि इस सेटिंग के बंद होने के बावजूद भी आप किसी स्पेस में मौजूद होने पर सभी को दिखाई देंगे. आपके फ़ॉलोअर्स हमेशा देख सकते हैं कि आप किन Spaces को होस्ट कर रहे हैं, सह-होस्ट कर रहे हैं या किनमें बोल रहे हैं. {{}}अधिक जानें{{}}\"",
