	"tipjar_input_rationale": "लोग उस उपयोगकर्ता नाम को भुगतान करेंगे, जिसे आपने ऊपर दर्ज किया है. अपने उपयोगकर्ता नाम को जोड़ कर और टिप्स को स्वीकार करके, आप अपने नाम, ईमेल पते और अन्य जानकारी सहित भुगतान सेवा पर अपने बारे में शेयर की गई जानकारी का खुलासा कर सकते हैं.",
	"tipjar_input_rationale_bitcoin": "लोग उस Bitcoin पते पर भुगतान करेंगे, जिसे आपने ऊपर दर्ज किया है.",
	"tipjar_input_rationale_kakao_pay": "\"लोग उस QR लिंक पर टिप्स भेजेंगे, जिसे आपने ऊपर दर्ज किया है.\nअपने QR लिंक को जोड़ कर और टिप्स को स्वीकार करके, आप अपने नाम, ईमेल पते और अन्य जानकारी सहित भुगतान सेवा पर अपने बारे में शेयर की गई जानकारी का खुलासा कर सकते हैं.\n\nKakao Pay QR लिंक को KakaoTalk More > ऊपर दाईं ओर स्कैनर > मनी कोड > क्लिपबोर्ड छवि आइकन पर देखा जा सकता है. लिंक को अपने क्लिपबोर्ड पर कॉपी करने के लिए आइकन पर टैप करें और उसके बाद लिंक को ऊपर पेस्ट करें.\"",
	"tipjar_input_rationale_paytm": "लोग उस Paytm से लिंक मोबाइल नंबर पर टिप्स भेजेंगे, जिसे आपने ऊपर दर्ज किया है. अपने मोबाइल नंबर को जोड़ कर और टिप्स को स्वीकार करके, आप अपने नाम, ईमेल पते, फ़ोन नंबर और अन्य जानकारी सहित भुगतान सेवा पर अपने बारे में शेयर की गई जानकारी को प्रकट कर सकते हैं.",
